
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  ArrowLeft, Save, Upload, FileCode, Shield, CheckCircle, Loader2
} from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { useAuth } from '../context/AuthContext';
import { ShopProduct } from '../types';

const ProductEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { addItem, updateItem, getStoreItem } = useShop();
  const { user } = useAuth();
  
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: 'software',
    images: [] as string[],
    stock: 100,
    isActive: true
  });

  useEffect(() => {
    if (id) {
      const item = getStoreItem(id);
      if (item) {
        setFormData({
          name: item.title,
          description: item.description,
          price: item.price,
          category: item.type === 'course' ? 'course' : 'software',
          images: [item.image],
          stock: 100,
          isActive: true
        });
      }
    }
  }, [id, getStoreItem]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
        if (id) {
            await updateItem('product', id, formData);
        } else {
            await addItem('product', formData);
        }
        navigate('/shop/dashboard');
    } catch (error) {
        console.error(error);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-20 pt-16">
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 sticky top-16 z-40">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={() => navigate('/shop/dashboard')} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors text-slate-500">
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-base md:text-lg font-bold text-slate-900 dark:text-white">
              {id ? 'Edit Product' : 'New Product'}
            </h1>
          </div>
          <button 
            type="submit" 
            form="product-form"
            disabled={isSubmitting}
            className="px-4 py-1.5 md:px-6 md:py-2 bg-emerald-600 text-white rounded-lg font-bold text-sm md:text-base hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-600/20 flex items-center gap-2 disabled:opacity-50"
          >
            {isSubmitting ? <Loader2 className="animate-spin" size={18}/> : <Save size={18} />}
            <span>Save Product</span>
          </button>
        </div>
      </header>

      <form id="product-form" onSubmit={handleSave} className="max-w-4xl mx-auto px-4 py-8 space-y-6">
        <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="sm:col-span-2">
                    <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Product Name</label>
                    <input 
                        required
                        type="text" 
                        value={formData.name} 
                        onChange={e => setFormData({...formData, name: e.target.value})} 
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold" 
                        placeholder="e.g. Trend Pro Indicator"
                    />
                </div>
                <div>
                    <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Category</label>
                    <select 
                        value={formData.category} 
                        onChange={e => setFormData({...formData, category: e.target.value})}
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold"
                    >
                        <option value="software">Software</option>
                        <option value="course">Course</option>
                        <option value="template">Template</option>
                        <option value="service">Service</option>
                        <option value="other">Other</option>
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Price ($)</label>
                    <input 
                        required
                        type="number" 
                        step="0.01"
                        value={formData.price} 
                        onChange={e => setFormData({...formData, price: Number(e.target.value)})} 
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold"
                    />
                </div>
                <div className="sm:col-span-2">
                    <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Description</label>
                    <textarea 
                        required
                        rows={4} 
                        value={formData.description} 
                        onChange={e => setFormData({...formData, description: e.target.value})} 
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white text-sm"
                    />
                </div>
            </div>
        </div>

        <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
            <h2 className="text-sm font-black uppercase text-slate-400 mb-6 tracking-widest border-b border-slate-100 dark:border-slate-800 pb-2">Image Assets</h2>
            <div className="space-y-4">
                <input 
                    type="text" 
                    placeholder="Enter main image URL" 
                    value={formData.images[0] || ''}
                    onChange={e => setFormData({...formData, images: [e.target.value]})}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white text-sm"
                />
                <div className="border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl p-8 text-center hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group">
                    <Upload size={32} className="mx-auto text-slate-300 group-hover:text-emerald-500 mb-4 transition-colors" />
                    <h3 className="font-bold text-slate-900 dark:text-white mb-1">Upload Local Assets</h3>
                    <p className="text-slate-500 text-xs uppercase font-bold tracking-tighter">.ex5, .ex4, .zip, .pdf (Max 50MB)</p>
                </div>
            </div>
        </div>
      </form>
    </div>
  );
};

export default ProductEditor;
